with flattened as (select id, service, log_ts, key, v from app_logs lateral view explode(context) x as key, v) select date_trunc('day', log_ts) as activity_day, size(collect_set(service)) as num_services, count(case when service = 'search' then 1 end) as search_count, count(*) filter (where service = 'billing') as billing_rows from flattened group by activity_day order by search_count desc nulls last;
